"""Safe zone phases, shrink interpolation, and damage outside the circle.

State lives in `match.zone` (`SafeZone`). The zone reads `match.clock`; the engine advances the
clock and calls `tick_zone` once per tick. Damage is returned, not applied: the engine passes
each entry to the combat module.

Timing: the wait and shrink values in `config.zone_phases` are scaled by `zone_time_scale` so
the whole zone timeline lasts `config.match_duration_minutes`. All numbers are local development
values, not original Rules of Survival zone data.
"""

import math

from solo_engine.config import SoloMatchConfig, ZonePhaseConfig
from solo_engine.geometry import distance, inside_any
from solo_engine.model import LifeState, SoloMatch

# Participants in these states cannot be hurt by the zone.
ZONE_IMMUNE_STATES = frozenset(
    {LifeState.WAITING, LifeState.ON_AIRCRAFT, LifeState.FREEFALL, LifeState.PARACHUTE, LifeState.ELIMINATED}
)
CENTRE_ATTEMPTS = 12


def raw_timeline_seconds(config: SoloMatchConfig) -> float:
    """Sum of the unscaled wait and shrink values of every phase."""
    return sum(phase.wait + phase.shrink for phase in config.zone_phases)


def zone_time_scale(config: SoloMatchConfig) -> float:
    """Factor applied to every wait and shrink so the timeline fills the match duration.

    A non-positive match duration or an empty phase list leaves the phase values unscaled.
    """
    raw = raw_timeline_seconds(config)
    target = config.match_duration_minutes * 60.0
    if raw <= 0 or target <= 0:
        return 1.0
    return target / raw


def phase_wait(config: SoloMatchConfig, phase_index: int) -> float:
    return config.zone_phases[phase_index].wait * zone_time_scale(config)


def phase_shrink(config: SoloMatchConfig, phase_index: int) -> float:
    return config.zone_phases[phase_index].shrink * zone_time_scale(config)


def timeline_seconds(config: SoloMatchConfig) -> float:
    """Seconds from `start_zone` until the final circle is reached."""
    return sum(phase_wait(config, i) + phase_shrink(config, i) for i in range(len(config.zone_phases)))


def initial_radius(match: SoloMatch) -> float:
    return match.map.initial_zone_radius or match.map.size * 0.75


def _phase(match: SoloMatch, phase_index: int) -> ZonePhaseConfig:
    return match.config.zone_phases[phase_index]


def pick_next_circle(match: SoloMatch, phase_index: int) -> tuple[float, float, float]:
    """Choose the circle that phase `phase_index` shrinks to.

    The new circle lies fully inside the current one, its centre is inside the map, and the
    centre avoids water and blockers when a few random tries allow it.
    """
    zone = match.zone
    size = match.map.size
    radius = max(0.0, _phase(match, phase_index).radius * initial_radius(match))
    max_offset = max(0.0, zone.radius - radius)
    avoid = tuple(match.map.water) + tuple(match.map.blockers)
    fallback: tuple[float, float] | None = None
    for _ in range(CENTRE_ATTEMPTS):
        angle = match.rng.uniform(0.0, 2.0 * math.pi)
        offset = max_offset * math.sqrt(match.rng.random())
        x = zone.center_x + math.cos(angle) * offset
        y = zone.center_y + math.sin(angle) * offset
        if not (0.0 <= x <= size and 0.0 <= y <= size):
            continue
        if fallback is None:
            fallback = (x, y)
        if not inside_any(x, y, avoid):
            return x, y, radius
    if fallback is not None:
        return fallback[0], fallback[1], radius
    x = min(max(zone.center_x, 0.0), size)
    y = min(max(zone.center_y, 0.0), size)
    if distance(x, y, zone.center_x, zone.center_y) > max_offset:
        x, y = zone.center_x, zone.center_y
    return x, y, radius


def _announce(match: SoloMatch, phase_index: int, wait_starts_at: float) -> None:
    zone = match.zone
    zone.phase_index = phase_index
    zone.state = "waiting"
    zone.dps = _phase(match, phase_index).dps
    zone.next_x, zone.next_y, zone.next_radius = pick_next_circle(match, phase_index)
    zone.phase_started_at = wait_starts_at
    zone.phase_ends_at = wait_starts_at + phase_wait(match.config, phase_index)
    match.emit(
        "zone_announce",
        phase=phase_index,
        x=zone.next_x,
        y=zone.next_y,
        radius=zone.next_radius,
        shrink_at=zone.phase_ends_at,
    )


def start_zone(match: SoloMatch) -> None:
    """Show the first circle. Call once when the match enters PLAYING."""
    zone = match.zone
    zone.center_x = match.map.size / 2.0
    zone.center_y = match.map.size / 2.0
    zone.radius = initial_radius(match)
    zone.start_x, zone.start_y, zone.start_radius = zone.center_x, zone.center_y, zone.radius
    _announce(match, 0, match.clock)


def tick_zone(match: SoloMatch, dt: float) -> None:
    """Advance the zone to `match.clock`. `dt` is accepted for symmetry; time comes from the clock."""
    zone = match.zone
    phases = match.config.zone_phases
    # Loop so one large step can cross several transitions.
    for _ in range(4 * len(phases) + 4):
        if zone.state == "waiting":
            if match.clock < zone.phase_ends_at:
                return
            zone.state = "shrinking"
            zone.start_x, zone.start_y, zone.start_radius = zone.center_x, zone.center_y, zone.radius
            zone.phase_started_at = zone.phase_ends_at
            zone.phase_ends_at = zone.phase_started_at + phase_shrink(match.config, zone.phase_index)
            match.emit("zone_shrink_start", phase=zone.phase_index, ends_at=zone.phase_ends_at)
            continue
        if zone.state == "shrinking":
            span = zone.phase_ends_at - zone.phase_started_at
            t = 1.0 if span <= 0 else min(max((match.clock - zone.phase_started_at) / span, 0.0), 1.0)
            zone.center_x = zone.start_x + (zone.next_x - zone.start_x) * t
            zone.center_y = zone.start_y + (zone.next_y - zone.start_y) * t
            zone.radius = zone.start_radius + (zone.next_radius - zone.start_radius) * t
            if t < 1.0:
                return
            zone.center_x, zone.center_y, zone.radius = zone.next_x, zone.next_y, zone.next_radius
            if zone.phase_index + 1 < len(phases):
                _announce(match, zone.phase_index + 1, zone.phase_ends_at)
                continue
            zone.state = "final"
            zone.dps = phases[zone.phase_index].dps
            match.emit("zone_final", phase=zone.phase_index, x=zone.center_x, y=zone.center_y, radius=zone.radius)
            return
        return


def _circle(match: SoloMatch, use_next: bool) -> tuple[float, float, float]:
    zone = match.zone
    if use_next and zone.state in ("waiting", "shrinking"):
        return zone.next_x, zone.next_y, zone.next_radius
    return zone.center_x, zone.center_y, zone.radius


def outside(match: SoloMatch, x: float, y: float, use_next: bool = False) -> bool:
    """True when (x, y) is outside the current (or next) circle. Always False before the zone starts."""
    if match.zone.state == "inactive":
        return False
    cx, cy, r = _circle(match, use_next)
    return distance(x, y, cx, cy) > r


def distance_to_safety(match: SoloMatch, x: float, y: float, use_next: bool = False) -> float:
    """Metres to walk to reach the current (or next) circle; 0 when already inside."""
    if match.zone.state == "inactive":
        return 0.0
    cx, cy, r = _circle(match, use_next)
    return max(0.0, distance(x, y, cx, cy) - r)


def seconds_until_shrink(match: SoloMatch) -> float:
    """Seconds until the announced circle starts to shrink: 0 while shrinking, inf when none is pending."""
    zone = match.zone
    if zone.state == "waiting":
        return max(0.0, zone.phase_ends_at - match.clock)
    if zone.state == "shrinking":
        return 0.0
    return math.inf


def zone_damage(match: SoloMatch, dt: float) -> list[tuple[str, float]]:
    """(participant_id, amount) for every grounded participant outside the current circle."""
    zone = match.zone
    if zone.state == "inactive" or dt <= 0 or zone.dps <= 0:
        return []
    amount = zone.dps * dt
    return [
        (p.participant_id, amount)
        for p in match.participants.values()
        if p.alive and p.life not in ZONE_IMMUNE_STATES and outside(match, p.x, p.y)
    ]
